architecture rtl of register_file is
    type register_array_t is array (0 to 31) of std_logic_vector(31 downto 0);
    signal registers : register_array_t;
begin
    process(clk, rst)
    begin
        if rst = '1' then
            registers <= (others => (others => '0'));
        elsif rising_edge(clk) then
